/**
 * Rendered demonstrator clips (Blender pipeline, tools/blender): one short clip per stretch step, played in sync
 * with the exercise timeline. A clip is four equal segments —
 *   approach (hands arrive, eyes close) | stretch (0 → 1, eased like the app) | release | retreat
 * — and the hold is the last stretch frame, frozen, so any hold time works without a longer video.
 * Clips show the affected LEFT side; the player mirrors them for the other side / view.
 */
import type { Scene } from './motion';
import eyeOpenInnerOut from './demo/eye-open.inner-out.json';
import eyeOpenPalmOut from './demo/eye-open.palm-out.json';

export interface ClipContact {
  hand: 'A' | 'B';
  finger: string;
  /** Contact at rest and at full stretch, 0..1 image coordinates of the clip. */
  from: [number, number];
  to: [number, number];
  fixed: boolean;
}

export interface DemoClip {
  id: string;
  fps: number;
  size: [number, number];
  duration: number;
  /** Length of each of the four segments (s). */
  segment: number;
  affected: 'left' | 'right';
  background: string;
  /** Affected eye centre and one ELC unit (x, y) in 0..1 image coordinates. */
  eye: [number, number];
  unit: [number, number];
  contacts: ClipContact[];
}

const CLIPS: Record<string, DemoClip> = {
  'eye-open/inner-out': eyeOpenInnerOut as unknown as DemoClip,
  'eye-open/palm-out': eyeOpenPalmOut as unknown as DemoClip,
};

export const clipFor = (exerciseId: string, stepId: string | undefined): DemoClip | undefined =>
  stepId ? CLIPS[`${exerciseId}/${stepId}`] : undefined;
export const hasClips = (exerciseId: string) => Object.keys(CLIPS).some((k) => k.startsWith(`${exerciseId}/`));
export const clipUrl = (c: DemoClip, ext: 'mp4' | 'hold.jpg' = 'mp4') => new URL(`demo/${c.id}.${ext}`, document.baseURI).href;

/**
 * Where the clip should be at this moment of the exercise: video time, and the playback rate at 1× speed
 * (0 = hold that frame still).
 */
export function clipTime(c: DemoClip, s: Scene): { t: number; rate: number } {
  const S = c.segment;
  const at = (seg: number, u: number) => Math.min(seg * S + Math.max(0, u) * S, (seg + 1) * S - 0.5 / c.fps);
  if (s.done) return { t: 0, rate: 0 };
  const inPhase = s.phaseT * s.phase.dur;
  switch (s.phase.key) {
    case 'prepare':
      // First time: the hands come in at normal speed, then wait on the skin. Later reps: already in place.
      return s.rep <= 1 ? { t: at(0, inPhase / S), rate: inPhase < S ? 1 : 0 } : { t: at(0, 1), rate: 0 };
    case 'stretch':
      return { t: at(1, s.phaseT), rate: S / s.phase.dur };
    case 'hold':
      return { t: at(1, 1), rate: 0 };
    case 'release':
      return { t: at(2, s.phaseT), rate: S / s.phase.dur };
    case 'rest':
      return s.rep >= s.reps ? { t: at(3, s.phaseT), rate: S / s.phase.dur } : { t: at(0, 1), rate: 0 };
    default:
      return { t: at(1, 1), rate: 0 };
  }
}

/** Does the clip need mirroring so the affected side lands where the 2D view puts it? */
export function clipFlip(c: DemoClip, affected: 'left' | 'right', mirror: boolean): boolean {
  // The 2D view puts the affected side on the screen's left when (affected = left) === mirror.
  const wantLeft = (affected === 'left') === mirror;
  const renderLeft = c.affected !== 'left'; // the character faces us: her left is on the screen's right
  return wantLeft !== renderLeft;
}
